     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import org.springframework.samples.petclinic.model.Owner;
     4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
     5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
     6	
     7	/**
     8	 * Shared derivation of an owner's {@code identityKey} — the single value that all duplicate
     9	 * detection is now expressed through. The key is
    10	 * {@code normalizedTelephone + "|" + (email or empty) + "|" + householdId}, where:
    11	 *
    12	 * <ul>
    13	 * <li>{@code normalizedTelephone} is the E.164 form (see {@link TelephoneE164});</li>
    14	 * <li>the email component is the lower-cased email, or empty when none is supplied; and</li>
    15	 * <li>{@code householdId} is the owner's deterministic household identifier, derived from its last
    16	 *     name and postcode (see {@link Household}).</li>
    17	 * </ul>
    18	 *
    19	 * <p>Two owners are duplicates only when their <em>whole</em> keys are equal. Because the telephone
    20	 * is part of the key, two members of the same household (same {@code householdId}) with different
    21	 * telephones have different keys and are both allowed.
    22	 */
    23	public final class OwnerIdentityKey {
    24	
    25	    private OwnerIdentityKey() {
    26	    }
    27	
    28	    /**
    29	     * Identity key for an incoming create-owner request (after {@link ValidateNewOwner}). The
    30	     * household component is the deterministic id derived from the request's last name and postcode,
    31	     * so the key matches the one the owner will carry once saved.
    32	     */
    33	    public static String forRequest(OwnerFieldsDto request) {
    34	        return build(request.getTelephone(), request.getEmail(), Household.idFor(request));
    35	    }
    36	
    37	    /** Identity key for an existing, stored owner. */
    38	    public static String forOwner(Owner owner) {
    39	        return build(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    40	    }
    41	
    42	    private static String build(String telephone, String email, String householdId) {
    43	        return normalizeTelephone(telephone) + "|" + normalizeEmail(email) + "|"
    44	                + (householdId == null ? "" : householdId);
    45	    }
    46	
    47	    /** E.164 form when the value can form one, otherwise the raw value so it only matches itself. */
    48	    private static String normalizeTelephone(String telephone) {
    49	        if (telephone == null) {
    50	            return "";
    51	        }
    52	        try {
    53	            return TelephoneE164.normalize(telephone);
    54	        }
    55	        catch (InvalidTelephoneException ex) {
    56	            return telephone;
    57	        }
    58	    }
    59	
    60	    /** Lower-cased email, or empty when none is supplied. */
    61	    private static String normalizeEmail(String email) {
    62	        if (email == null || email.isBlank()) {
    63	            return "";
    64	        }
    65	        return email.trim().toLowerCase();
    66	    }
    67	}

