     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import net.officefloor.plugin.variable.Val;
     4	import org.springframework.samples.petclinic.model.Owner;
     5	import org.springframework.samples.petclinic.repository.OwnerRepository;
     6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
     7	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerIdentityException;
     8	
     9	/**
    10	 * The duplicate-detection step of {@code POST /api/owners}. Duplicate detection is expressed through
    11	 * the owner's {@code identityKey} (see {@link OwnerIdentityKey}): a request is a duplicate only when
    12	 * an existing owner carries the <em>same whole key</em> — normalized telephone, email and
    13	 * {@code householdId} all equal. Because the telephone is part of the key, two members of the same
    14	 * household (same last name and postcode) with different telephones have different keys and are both
    15	 * allowed; only a genuine re-submission of the same owner is rejected with 409.
    16	 *
    17	 * <p>The {@code sharesHousehold} hint bypasses this block: a request that declares itself a member
    18	 * of a shared household is allowed through and created as a legitimate second member (and is not
    19	 * flagged as a possible duplicate, see {@link AssignPossibleDuplicate}).
    20	 *
    21	 * <p>Runs after {@link ValidateNewOwner} has normalized the request and before {@link BuildOwner},
    22	 * so a duplicate is a 409 rather than a persisted record.
    23	 */
    24	public class CheckOwnerIdentityUnique {
    25	
    26	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
    27	            throws DuplicateOwnerIdentityException {
    28	        if (Household.sharesHousehold(request)) {
    29	            return; // declared household member: bypass the duplicate block
    30	        }
    31	        String identityKey = OwnerIdentityKey.forRequest(request);
    32	        for (Owner owner : ownerRepository.findAll()) {
    33	            if (owner.isDeleted()) {
    34	                continue; // a soft-deleted owner no longer blocks a new create
    35	            }
    36	            if (identityKey.equals(OwnerIdentityKey.forOwner(owner))) {
    37	                throw new DuplicateOwnerIdentityException(Household.idFor(request));
    38	            }
    39	        }
    40	    }
    41	}

