     6	/**
     7	 * Assigns the owner's deterministic {@code householdId} before it is saved. The identifier is
     8	 * derived purely from the owner's last name and postcode (see {@link Household}), so every owner in
     9	 * the same household receives the same value automatically — no request has to opt in, and the
    10	 * {@code sharesHousehold} hint no longer creates the link (it only bypasses the duplicate block in
    11	 * {@link CheckOwnerIdentityUnique}).
    12	 *
    13	 * <p>Runs after {@link BuildOwner} has produced the {@link Owner} and before {@link SaveOwner}
    14	 * persists it. Mutates the entity in place so {@link SaveOwner} stores the id.
    15	 */
    16	public class AssignHousehold {
    17	
    18	    public void service(@Val Owner owner) {
    19	        owner.setHouseholdId(Household.idFor(owner));
    20	    }
    21	}

