     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.nio.charset.StandardCharsets;
     4	import java.security.MessageDigest;
     5	import java.security.NoSuchAlgorithmException;
     6	
     7	import org.springframework.samples.petclinic.model.Owner;
     8	import org.springframework.samples.petclinic.repository.OwnerRepository;
     9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
    10	
    11	/**
    12	 * Shared, deterministic household identity for the create-owner pipeline.
    13	 *
    14	 * <p>An owner's household is keyed purely on its last name and postcode: the {@code householdId} is
    15	 * the first 12 hex characters (upper-case) of SHA-256 over {@code normalizedLastName + "|" +
    16	 * postcode}. Because it is derived from nothing but those two values, every owner with the same last
    17	 * name and postcode receives the same identifier automatically — no owner has to opt in, and the id
    18	 * is identical before and after the owner is saved.
    19	 *
    20	 * <p>The last name is normalized (trimmed, internal whitespace collapsed, lower-cased) so that
    21	 * cosmetic differences do not split a household; the postcode is compared as its trimmed value.
    22	 *
    23	 * <p>Used by {@link AssignHousehold} (which stores the id on the new owner), by
    24	 * {@link CheckOwnerIdentityUnique} (which rejects a second owner already in the household unless the
    25	 * request declares {@code sharesHousehold}) and by {@link OwnerIdentityKey}.
    26	 */
    27	final class Household {
    28	
    29	    private Household() {
    30	    }
    31	
    32	    /** The deterministic household id the given create-owner request belongs to. */
    33	    static String idFor(OwnerFieldsDto request) {
    34	        return deriveId(normalizeName(request.getLastName()), normalizePostcode(request.getPostcode()));
    35	    }
    36	
    37	    /** The deterministic household id an existing, stored owner belongs to. */
    38	    static String idFor(Owner owner) {
    39	        return deriveId(normalizeName(owner.getLastName()), normalizePostcode(owner.getPostcode()));
    40	    }
    41	
    42	    /**
    43	     * Whether the request declares itself a member of a shared household. This only bypasses the
    44	     * duplicate block (see {@link CheckOwnerIdentityUnique}); it never affects which household id an
    45	     * owner is assigned, which is fixed by its last name and postcode.
    46	     */
    47	    static boolean sharesHousehold(OwnerFieldsDto request) {
    48	        return Boolean.TRUE.equals(request.getSharesHousehold());
    49	    }
    50	
    51	    /**
    52	     * The number of stored owners in {@code owner}'s household — those sharing its
    53	     * {@code householdId}, the owner itself included. Zero when the owner has no household id.
    54	     */
    55	    static int memberCount(Owner owner, OwnerRepository ownerRepository) {
    56	        String householdId = owner.getHouseholdId();
    57	        if (householdId == null) {
    58	            return 0;
    59	        }
    60	        int count = 0;
    61	        for (Owner other : ownerRepository.findAll()) {
    62	            if (householdId.equals(other.getHouseholdId())) {
    63	                count++;
    64	            }
    65	        }
    66	        return count;
    67	    }
    68	
    69	    /** First 12 upper-hex characters of SHA-256 over {@code lastName + "|" + postcode}. */
    70	    private static String deriveId(String lastName, String postcode) {
    71	        try {
    72	            byte[] digest = MessageDigest.getInstance("SHA-256")
    73	                    .digest((lastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
    74	            StringBuilder sb = new StringBuilder(12);
    75	            for (int i = 0; i < 6; i++) {
    76	                sb.append(String.format("%02X", digest[i]));
    77	            }
    78	            return sb.toString();
    79	        }
    80	        catch (NoSuchAlgorithmException ex) {
    81	            throw new IllegalStateException("SHA-256 unavailable", ex);
    82	        }
    83	    }
    84	
    85	    /** Lower-case and collapse all runs of whitespace to a single space, trimmed. */
    86	    private static String normalizeName(String value) {
    87	        if (value == null) {
    88	            return "";
    89	        }
    90	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    91	    }
    92	
    93	    /** Trimmed postcode, or empty when none is supplied. */
    94	    private static String normalizePostcode(String postcode) {
    95	        return (postcode == null) ? "" : postcode.trim();
    96	    }
    97	}

