     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.util.Set;
     4	import java.util.regex.Pattern;
     5	
     6	import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;
     7	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
     8	
     9	/**
    10	 * Shared normalization for an owner's optional {@code email}. When absent (null or blank) the
    11	 * email is left unset; when present it must be a syntactically valid address and is stored and
    12	 * returned lower-cased. An invalid address is rejected with 400 via {@link InvalidEmailException}.
    13	 * An address whose domain is on the disposable-domain blocklist is rejected with 400 via
    14	 * {@link DisposableEmailDomainException}.
    15	 */
    16	final class OwnerEmail {
    17	
    18	    /** Syntactic address check: non-empty local part, one '@', and a dotted domain. */
    19	    private static final Pattern EMAIL = Pattern.compile(
    20	            "^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
    21	
    22	    /** Disposable email domains that are never accepted (compared case-insensitively). */
    23	    private static final Set<String> DISPOSABLE_DOMAINS = Set.of(
    24	            "mailinator.com", "tempmail.com", "guerrillamail.com");
    25	
    26	    private OwnerEmail() {
    27	    }
    28	
    29	    /**
    30	     * Returns the normalized (lower-cased) email, or {@code null} when none was supplied.
    31	     *
    32	     * @throws InvalidEmailException when an email is present but not syntactically valid.
    33	     * @throws DisposableEmailDomainException when the email's domain is on the disposable blocklist.
    34	     */
    35	    static String normalize(String email) throws InvalidEmailException, DisposableEmailDomainException {
    36	        if (email == null || email.isBlank()) {
    37	            return null;
    38	        }
    39	        String trimmed = email.trim();
    40	        if (!EMAIL.matcher(trimmed).matches()) {
    41	            throw new InvalidEmailException(email);
    42	        }
    43	        String normalized = trimmed.toLowerCase();
    44	        String domain = normalized.substring(normalized.indexOf('@') + 1);
    45	        if (DISPOSABLE_DOMAINS.contains(domain)) {
    46	            throw new DisposableEmailDomainException(email);
    47	        }
    48	        return normalized;
    49	    }
    50	}

