     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.util.LinkedHashMap;
     4	import java.util.Map;
     5	import java.util.regex.Pattern;
     6	
     7	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
     8	
     9	/**
    10	 * Shared normalization for an owner's {@code telephone} to E.164 form. Spaces, dashes and
    11	 * brackets are stripped. A leading '+' and country code are kept when present; otherwise the
    12	 * country code '+61' is assumed and a single leading '0' is dropped from the national digits.
    13	 * The result must have 8 to 15 digits after the '+'. So {@code "0412 345 678"} becomes {@code
    14	 * "+61412345678"}. In addition, the national-number length must match the country code: '+61'
    15	 * requires 9 national digits and '+1' requires 10. A number that cannot form valid E.164, or
    16	 * whose national length is wrong for its country, is rejected with 400 via {@link
    17	 * InvalidTelephoneException}.
    18	 */
    19	final class TelephoneE164 {
    20	
    21	    /** Characters removed before interpreting the number. */
    22	    private static final Pattern SEPARATORS = Pattern.compile("[\\s\\-()]");
    23	
    24	    /** 8 to 15 digits, the E.164 length bound (country code plus national digits). */
    25	    private static final Pattern E164_DIGITS = Pattern.compile("\\d{8,15}");
    26	
    27	    /**
    28	     * Country code (without '+') to the exact number of national digits it requires. Ordered
    29	     * longest-prefix-first so a code is matched before any shorter code that is a suffix of it.
    30	     */
    31	    private static final Map<String, Integer> NATIONAL_LENGTH = new LinkedHashMap<>();
    32	
    33	    static {
    34	        NATIONAL_LENGTH.put("61", 9);
    35	        NATIONAL_LENGTH.put("1", 10);
    36	    }
    37	
    38	    private TelephoneE164() {
    39	    }
    40	
    41	    /**
    42	     * Returns the E.164 string (a '+' followed by 8 to 15 digits) for the given raw telephone.
    43	     *
    44	     * @throws InvalidTelephoneException when no valid E.164 string can be formed.
    45	     */
    46	    static String normalize(String telephone) throws InvalidTelephoneException {
    47	        if (telephone == null) {
    48	            throw new InvalidTelephoneException(null);
    49	        }
    50	        String cleaned = SEPARATORS.matcher(telephone).replaceAll("");
    51	        String digits;
    52	        if (cleaned.startsWith("+")) {
    53	            digits = cleaned.substring(1);
    54	        }
    55	        else {
    56	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
    57	            digits = "61" + national;
    58	        }
    59	        if (!E164_DIGITS.matcher(digits).matches()) {
    60	            throw new InvalidTelephoneException(telephone);
    61	        }
    62	        for (Map.Entry<String, Integer> country : NATIONAL_LENGTH.entrySet()) {
    63	            String code = country.getKey();
    64	            if (digits.startsWith(code)) {
