    17	/**
    18	 * First step of {@code POST /api/owners}. Normalizes the address to its canonical form (see
    19	 * {@link OwnerAddress}) and stores it back on the request, then rejects a request that is missing
    20	 * or blank in any required field (firstName, lastName, address, city, telephone) — the address
    21	 * being tested for blankness after normalization — with a 400 whose body lists the offending field
    22	 * names. Then normalizes the telephone to E.164 form (see {@link
    23	 * TelephoneE164}), storing the E.164 value back on the request so later steps persist and return
    24	 * it; a telephone that cannot form valid E.164 is rejected with a 400. Finally, when a {@code
    25	 * postcode} is supplied it is validated against the city's region (see {@link Postcode}); a
    26	 * malformed or out-of-range postcode is rejected with a 400, while an absent postcode is accepted.
    27	 * A supplied {@code registrationDate} later than the server date is rejected with a 400, while an
    28	 * absent registration date (defaulted later to the server date) is accepted. Runs before
    29	 * {@link BuildOwner} maps the body to an {@link
    30	 * org.springframework.samples.petclinic.model.Owner}.
    31	 */
    32	public class ValidateNewOwner {
    33	
    34	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
    35	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
    36	            InvalidPostcodeException, FutureRegistrationDateException, DisposableEmailDomainException {
    37	        // Address may arrive structured (addressLine1 [+ addressLine2]) or as the flat 'address'.
    38	        // The structured form is preferred whenever addressLine1 is non-blank; otherwise the flat
    39	        // value is used (backward-compatible). Whichever fields are supplied are normalized, and the
    40	        // flat 'address' everything downstream reads is composed from the structured fields when they
    41	        // win: normalized addressLine1 plus, when addressLine2 is present, a space and normalized
    42	        // addressLine2.
    43	        String addressLine1 = OwnerAddress.normalize(request.getAddressLine1());
    44	        if (!addressLine1.isEmpty()) {
    45	            String addressLine2 = OwnerAddress.normalize(request.getAddressLine2());
    46	            request.setAddressLine1(addressLine1);
    47	            request.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
    48	            request.setAddress(addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2);
    49	        }
    50	        else {
    51	            request.setAddress(OwnerAddress.normalize(request.getAddress()));
    52	        }
    53	        List<String> missing = new ArrayList<>();
    54	        if (isBlank(request.getFirstName())) {
    55	            missing.add("firstName");
    56	        }
    57	        if (isBlank(request.getLastName())) {
    58	            missing.add("lastName");
    59	        }
    60	        if (isBlank(request.getAddress())) {
    61	            missing.add("address");
    62	        }
    63	        if (isBlank(request.getCity())) {
    64	            missing.add("city");
    65	        }
    66	        if (isBlank(request.getTelephone())) {
    67	            missing.add("telephone");
    68	        }
    69	        if (!missing.isEmpty()) {
    70	            throw new MissingOwnerFieldsException(missing);
    71	        }
    72	        request.setTelephone(TelephoneE164.normalize(request.getTelephone()));
    73	        request.setEmail(OwnerEmail.normalize(request.getEmail()));
    74	        // Postcode is optional; when present it must be a 4-digit code valid for the city's region.
    75	        Postcode.validate(request.getPostcode(), request.getCity());
    76	        // Registration date is optional; when supplied it may be back-dated but never into the future.
    77	        LocalDate registrationDate = request.getRegistrationDate();
    78	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
    79	            throw new FutureRegistrationDateException(registrationDate);
    80	        }
    81	        validated.set(request);
    82	    }
    83	
    84	    private static boolean isBlank(String value) {
    85	        return value == null || value.isBlank();
    86	    }
    87	}

