     7	/**
     8	 * Assigns the owner's {@code namesakeCount}: the number of existing owners that, at this moment
     9	 * before the new owner is persisted, share the same first name and last name (each compared
    10	 * case-insensitively). Runs after {@link BuildOwner} has produced the {@link Owner} and before
    11	 * {@link SaveOwner} persists it, so {@link OwnerRepository#findAll()} returns only the pre-existing
    12	 * owners and the new owner never counts itself. Mutates the entity in place so {@link SaveOwner}
    13	 * stores the value and later reads return it.
    14	 */
    15	public class AssignNamesakeCount {
    16	
    17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
    18	        String firstName = owner.getFirstName();
    19	        String lastName = owner.getLastName();
    20	        int count = 0;
    21	        for (Owner other : ownerRepository.findAll()) {
    22	            if (equalsIgnoreCase(firstName, other.getFirstName())
    23	                    && equalsIgnoreCase(lastName, other.getLastName())) {
    24	                count++;
    25	            }
    26	        }
    27	        owner.setNamesakeCount(count);
    28	    }
    29	
    30	    private static boolean equalsIgnoreCase(String a, String b) {
    31	        return (a == null) ? (b == null) : a.equalsIgnoreCase(b);
    32	    }
    33	}

