1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Assigns the owner's soft-match flags {@code possibleDuplicate} / {@code possibleDuplicateOf}. A
10	 * household duplicate (an owner already in this request's household) has already been rejected with
11	 * 409 by {@link CheckOwnerIdentityUnique}, so every owner reaching this step is being created. This
12	 * step flags the weaker overlap: an owner that shares an existing owner's {@code lastName} (compared
13	 * case-insensitively) and {@code postcode} but carries a <em>different</em> telephone. When such a
14	 * match exists {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to the matching
15	 * owner's id (the lowest id when several match, for determinism); otherwise {@code possibleDuplicate}
16	 * is false and {@code possibleDuplicateOf} left absent.
17	 *
18	 * <p>A declared household member (a request with {@code sharesHousehold} true, which reached this
19	 * step by bypassing the duplicate block) is <em>not</em> a suspected duplicate: it has explicitly
20	 * declared it shares the household, so its flags are left unset.
21	 *
22	 * <p>Runs after {@link BuildOwner} has produced the {@link Owner} and before {@link SaveOwner}
23	 * persists it, so {@link OwnerRepository#findAll()} returns only the pre-existing owners and the new
24	 * owner never matches itself. Mutates the entity in place so {@link SaveOwner} stores the values and
25	 * later reads return them.
26	 */
27	public class AssignPossibleDuplicate {
28	
29	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
30	        if (Household.sharesHousehold(request)) {
